// Uses the public feed embedded on https://www.msauofa.ca/ (checked 9 October 2026).
// Feed exposes a weekday but no full date; display its weekday rather than infer a date.
let prayerData=null,prayerError=false,prayerLoading=false,prayerRequest=0,prayerLoadedAt=0;
function prayerSection(){return `<section class="section prayer" id="prayer" aria-labelledby="prayer-title"><div class="sectiontop"><div><div class="eyebrow">${tr('A moment for prayer','وقت للصلاة')}</div><h2 id="prayer-title">${tr('Prayer times on campus.','مواقيت الصلاة في الجامعة.')}</h2><p id="prayer-date"></p></div></div><div id="prayer-times" class="prayer-grid" aria-live="polite"></div><div class="prayer-meta"><p>${tr('Prayer start times · Edmonton. Congregational and Friday prayer times may differ.','أوقات دخول الصلاة · إدمونتون. قد تختلف أوقات الإقامة وصلاة الجمعة.')}</p></div></section>`}
function drawPrayer(){const box=document.querySelector('#prayer-times');if(!box)return;const days={Sunday:'الأحد',Monday:'الاثنين',Tuesday:'الثلاثاء',Wednesday:'الأربعاء',Thursday:'الخميس',Friday:'الجمعة',Saturday:'السبت'};document.querySelector('#prayer-date').textContent=prayerData?tr(prayerData.Day,days[prayerData.Day])+' · '+tr('Edmonton','إدمونتون'):'';
if(prayerLoading&&!prayerData){box.innerHTML='<p class="prayer-status">'+tr('Loading prayer times…','جارٍ تحميل مواقيت الصلاة…')+'</p>';return}
if(prayerError||!prayerData){box.innerHTML='<p class="prayer-status">'+tr('Prayer times are temporarily unavailable. Please check your campus prayer schedule.','مواقيت الصلاة غير متاحة مؤقتاً. راجع جدول الصلاة في الجامعة.')+'</p>';return}
box.innerHTML=[['Fajr','الفجر'],['Dhuhr','الظهر'],['Asr','العصر'],['Maghrib','المغرب'],['Isha','العشاء']].map(([key,ar])=>{const match=prayerData[key].match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);let h=Number(match[1])%12+(match[3].toUpperCase()==='PM'?12:0);const time=new Date(Date.UTC(2000,0,1,h,Number(match[2])));return '<div class="prayer-time"><span>'+tr(key,ar)+'</span><b>'+new Intl.DateTimeFormat(lang==='ar'?'ar-CA':'en-CA',{timeZone:'UTC',hour:'numeric',minute:'2-digit',hour12:true}).format(time)+'</b></div>'}).join('')}
async function loadPrayer(){if(prayerLoading)return;const request=++prayerRequest;prayerLoading=true;prayerError=false;drawPrayer();const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{const r=await fetch('https://api.msauofa.ca/prayer-times',{signal:controller.signal,cache:'no-store'});if(!r.ok)throw Error();const j=await r.json();if(!['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].includes(j.Day)||!['Fajr','Dhuhr','Asr','Maghrib','Isha'].every(k=>/^(0?[1-9]|1[0-2]):[0-5]\d\s*(AM|PM)$/i.test(j[k])))throw Error();if(request===prayerRequest){prayerData=j;prayerLoadedAt=Date.now()}}catch{if(request===prayerRequest){prayerError=true;prayerData=null}}finally{clearTimeout(timeout);if(request===prayerRequest){prayerLoading=false;drawPrayer()}}}
function bindPrayer(){if(!prayerData||Date.now()-prayerLoadedAt>=30*60*1000)loadPrayer();else drawPrayer()}
setInterval(()=>{if(document.visibilityState==='visible'&&currentSitePage==='resources')loadPrayer()},30*60*1000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&currentSitePage==='resources'&&(!prayerData||Date.now()-prayerLoadedAt>=30*60*1000))loadPrayer()});
